package com.ems.dao;
 import com.ems.model.Employee; import com.ems.util.DBConnection; import java.sql.*; import java.time.LocalDate; import java.util.*;
public class EmployeeDAO {
 private Employee map(ResultSet r)throws SQLException{Employee e=new Employee();e.setEmployeeId(r.getLong("employee_id"));e.setFullName(r.getString("full_name"));e.setEmail(r.getString("email"));e.setPhone(r.getString("phone"));e.setDepartment(r.getString("department"));e.setDesignation(r.getString("designation"));e.setSalary(r.getBigDecimal("salary"));e.setJoiningDate(r.getDate("joining_date").toLocalDate());e.setEmploymentStatus(r.getString("employment_status"));e.setAddress(r.getString("address"));return e;}
 public List<Employee> findAll(String search,String department,String status)throws SQLException{StringBuilder q=new StringBuilder("SELECT * FROM employees WHERE 1=1");List<String> a=new ArrayList<>();if(search!=null&&!search.isBlank()){q.append(" AND (CAST(employee_id AS CHAR) LIKE ? OR full_name LIKE ? OR email LIKE ?)");String s="%"+search.trim()+"%";a.add(s);a.add(s);a.add(s);}if(department!=null&&!department.isBlank()){q.append(" AND department=?");a.add(department);}if(status!=null&&!status.isBlank()){q.append(" AND employment_status=?");a.add(status);}q.append(" ORDER BY created_at DESC");try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q.toString())){for(int i=0;i<a.size();i++)p.setString(i+1,a.get(i));try(ResultSet r=p.executeQuery()){List<Employee> out=new ArrayList<>();while(r.next())out.add(map(r));return out;}}}
 public Employee findById(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM employees WHERE employee_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 public void insert(Employee e)throws SQLException{String q="INSERT INTO employees(full_name,email,phone,department,designation,salary,joining_date,employment_status,address) VALUES(?,?,?,?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){set(p,e);p.executeUpdate();}}
 public void update(Employee e)throws SQLException{String q="UPDATE employees SET full_name=?,email=?,phone=?,department=?,designation=?,salary=?,joining_date=?,employment_status=?,address=? WHERE employee_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){set(p,e);p.setLong(10,e.getEmployeeId());if(p.executeUpdate()==0)throw new SQLException("Employee not found");}}
 private void set(PreparedStatement p,Employee e)throws SQLException{p.setString(1,e.getFullName());p.setString(2,e.getEmail());p.setString(3,e.getPhone());p.setString(4,e.getDepartment());p.setString(5,e.getDesignation());p.setBigDecimal(6,e.getSalary());p.setDate(7,java.sql.Date.valueOf(e.getJoiningDate()));p.setString(8,e.getEmploymentStatus());p.setString(9,e.getAddress());}
 public boolean delete(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM employees WHERE employee_id=?")){p.setLong(1,id);return p.executeUpdate()>0;}}
 public long count()throws SQLException{return scalar("SELECT COUNT(*) FROM employees");} public long activeCount()throws SQLException{return scalar("SELECT COUNT(*) FROM employees WHERE employment_status='Active'");} public long departmentCount()throws SQLException{return scalar("SELECT COUNT(DISTINCT department) FROM employees");} public long recentCount()throws SQLException{return scalar("SELECT COUNT(*) FROM employees WHERE created_at >= CURRENT_DATE - INTERVAL 30 DAY");} private long scalar(String q)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}
}
